dtsPropsFor.QuickAccessCard:
href: string;
  /** A lucide-react icon component, passed uninstantiated (e.g. `icon={BookOpen}`). */
  icon: React.ComponentType<{ className?: string; size?: string | number; strokeWidth?: string | number; color?: string }>;
  title: string;
  description: string;
  /** Accent border + accent body text, for the one card that should draw the eye. */
  highlight?: boolean;
  /** Short uppercase pill in the top-right corner (ignored when `comingSoon`). */
  badge?: string;
  /** Stagger for the fade-in-up entrance, in ms. */
  delay?: number;
  /** Locks the card: dimmed, not a link, with a padlock + "Coming Soon" overlay. */
  comingSoon?: boolean;

dtsPropsFor.FooterAccordion:
title: string;
  children?: React.ReactNode;
  defaultOpen?: boolean;
  /** Drops the bottom divider, for the last row in a stack. */
  isLast?: boolean;

dtsPropsFor.PreghieraExpand:
/** Full prayer text; collapsed behind a "read more" control until expanded. */
  testo: string;
  /** Label for the expand control, e.g. "Leggi la preghiera". */
  labelRead: string;

dtsPropsFor.ConfirmModal:
open: boolean;
  title: string;
  message: string;
  onConfirm: () => void;
  onCancel: () => void;
  /** Disables both buttons and shows `loadingLabel` on the confirm button. */
  loading?: boolean;
  /** Confirm button text (defaults to "Elimina"). */
  confirmLabel?: string;
  loadingLabel?: string;
  /** "danger" (red, default) for deletions, "primary" for everything else. */
  tone?: "danger" | "primary";

dtsPropsFor.StatTile:
label: string;
  value: number | string;
  /** Secondary line under the value, e.g. "+12 questo mese". */
  detail?: string;
  /** A lucide-react icon component, passed uninstantiated. */
  icon: React.ComponentType<{ className?: string; size?: string | number; strokeWidth?: string | number; color?: string }>;

dtsPropsFor.BarList:
/** Ordered categories; every value is also printed, never colour-only. */
  data: { label: string; value: number }[];
  /** Unit suffix shown next to each value, e.g. "persone". */
  unit: string;

dtsPropsFor.ColumnChart:
data: { label: string; fullLabel: string; value: number }[];
  unit: string;
  title: string;

dtsPropsFor.EventRegistrations:
events: {
    id: string;
    titolo: string;
    data: string;
    persone: number;
    iscrizioni: number;
    pagate: number;
    postiDisponibili?: number;
    passato: boolean;
  }[];

dtsPropsFor.UrgentAvvisiBanner:
avvisi: {
    key: string;
    titolo: string;
    messaggio: string;
    link?: string;
  }[];

dtsPropsFor.LegalDocument:
copy: {
    eyebrow: string;
    title: string;
    updatedLabel: string;
    intro: string;
    tocTitle: string;
    sections: { id: string; title: string; paragraphs?: string[]; items?: string[] }[];
    languageNotice?: string;
    related: { href: string; label: string };
  };
  updatedAt: string;
  /** Locale tag, e.g. "it" or "ar"; drives date formatting and direction. */
  locale: string;
